"""Torch fallback for gated activation kernels."""

import torch
import torch.nn.functional as F


def _gate_up_hidden(gate_up: torch.Tensor, layout: str) -> int:
    if gate_up.ndim == 0:
        raise ValueError("gate_up must have at least one dimension")
    if gate_up.shape[-1] % 2 != 0:
        raise ValueError(
            f"gate_up last dimension must be even, got {gate_up.shape[-1]}"
        )
    hidden = int(gate_up.shape[-1] // 2)
    if layout == "interleaved_i8" and hidden % 8 != 0:
        raise ValueError(
            "interleaved_i8 gate/up hidden dimension must be divisible by 8, "
            f"got {hidden}"
        )
    if layout not in ("contiguous", "interleaved_i8"):
        raise ValueError(f"unsupported gate/up layout {layout!r}")
    return hidden


def gated_activation_torch(
    gate_up: torch.Tensor,
    *,
    activation: str,
    layout: str,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    hidden = _gate_up_hidden(gate_up, layout)
    expected_shape = (*gate_up.shape[:-1], hidden)
    if out is not None and out.shape != expected_shape:
        raise ValueError(
            f"out shape must be {expected_shape}, got {tuple(out.shape)}"
        )
    if layout == "interleaved_i8":
        blocks = gate_up.reshape(*gate_up.shape[:-1], hidden // 8, 16)
        gate = blocks[..., :8]
        up = blocks[..., 8:]
    else:
        gate, up = gate_up.split(hidden, dim=-1)
    if activation == "silu":
        activated = F.silu(gate)
    elif activation == "gelu_tanh":
        activated = F.gelu(gate, approximate="tanh")
    else:
        raise ValueError(f"unsupported gated activation {activation!r}")
    result = (activated * up).reshape(expected_shape)
    if out is not None:
        out.copy_(result)
        return out
    return result


__all__ = ["gated_activation_torch"]
